{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "NavigationScreen",
    "description": "One screen of a NavigationStack: its title, the title Back shows on the screen pushed after it, its end content and its content. Returned by NavigationStack's root and renderScreen; it renders nothing on its own.",
    "props": [
      {
        "name": "title",
        "type": "string",
        "description": "Shown in the bar while the screen is on top, and read first when it arrives.",
        "required": true
      },
      {
        "name": "backTitle",
        "type": "string",
        "description": "What Back reads on the screen pushed on top of this one. Defaults to title."
      },
      {
        "name": "titleDisplayMode",
        "type": "'large' | 'inline'",
        "description": "How the title shows. 'large' puts it above the content in a large bold type, scrolling with the content; once it has scrolled under the bar, the bar shows the title instead. Use it for a top-level screen, as iOS does.",
        "default": "'inline'"
      },
      {
        "name": "endContent",
        "type": "ReactNode",
        "description": "Content at the end of the bar while the screen is on top."
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "The screen's content. It scrolls on its own and keeps its scroll position while covered."
      }
    ],
