    "usage": {
      "description": "Use NavigationStack for hierarchical drill-down on phones: lists of settings, folders, a list and its detail. Call push from a row with useNavigationStack inside a screen.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Keep the path in the app's state (or the URL) and give entries stable keys, so screens keep their state as the stack changes."
        },
        {
          "guidance": true,
          "description": "Push from the control the person activated (a row's onClick): focus returns to it when the screen is popped."
        },
        {
          "guidance": false,
          "description": "Don't use it for top-level sections that people switch between; those are tabs or a sidebar, which keep each section's own stack."
